// Accesses an optional attribute without checking it first. The validator
// rejects this policy before approval; enforcement points must still deny if
// one gets through.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource) when { resource.server == "untrusted" };

// Needs the deployment extension ToolArgs = { recipient_domain?: String }.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"send_email")
when { context has args && context.args has recipient_domain && context.args.recipient_domain != "example.org" };

// Needs the deployment extension ToolArgs = { recipient_domain?: String }.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"send_email")
when { context has args && context.args has recipient_domain && context.args.recipient_domain != "example.org" };

// Needs the deployment extension ToolArgs = { amount?: Long }.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"post_ledger")
when { context has args && context.args has amount && context.args.amount > 1000 };

// Needs the deployment extension ToolArgs = { amount?: Long }.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"post_ledger")
when { context has args && context.args has amount && context.args.amount > 1000 };

// Needs the deployment extension ToolArgs = { amount?: Long }.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"post_ledger")
when { context has args && context.args has amount && context.args.amount > 1000 };

// Reads an optional attribute without checking it first: the validator
// rejects this policy before approval, and its evaluation fails for a tool
// without a server.
permit (principal, action == WhiteTower::Action::"tool.invoke", resource) when { resource.server == "trusted" };

